 async function pollMessageBadge(){if(mode!=='tenant'||!S.me)return;try{S.data.notifications=await call('/api/notifications');for(const [target,label] of [['messages','unread messages'],['documents','new documents']]){const count=S.data.notifications.filter(n=>n.target===target&&!n.is_read).length;const link=document.querySelector('[data-do="nav"][data-page="'+target+'"]');if(!link)continue;let badge=link.querySelector('.count');if(count){if(!badge){link.insertAdjacentHTML('beforeend','<span class="count" aria-label="'+count+' '+label+'">'+count+'</span>');badge=link.querySelector('.count');}else badge.textContent=String(count);}else if(badge)badge.remove();}refreshBell();}catch{}}
 function tmRerender(){const had=document.activeElement&&document.activeElement.id==='tm-body';const pos=had?document.activeElement.selectionStart:0;shell();if(had){const ta=document.getElementById('tm-body');if(ta){ta.focus();ta.setSelectionRange(pos,pos);}}}
 function tmMarkSeen(){if(S.page!=='messages'||!S.data.messages)return;const t=conversationThreads(S.data.messages).find(x=>x.id===TM.thread);if(!t)return;const seen=seenStore.get();const last=t.items[t.items.length-1].id;if((seen[t.id]||0)<last){const first=!seen[t.id];seen[t.id]=last;seenStore.set(seen);setTimeout(()=>{document.querySelectorAll('.ib-item.active').forEach(el=>{el.classList.remove('unread');const tg=el.querySelector('.ib-tag.warn');if(tg){tg.textContent='Answered';tg.classList.remove('warn');}});},1200);}}
