 new MutationObserver(()=>{const th=document.getElementById('tm-thread');if(th&&th.dataset.k!==String(TM.thread)+':'+th.children.length){th.dataset.k=String(TM.thread)+':'+th.children.length;th.scrollTop=th.scrollHeight;tmMarkSeen();const ta=document.getElementById('tm-body');const send=document.getElementById('tm-send');if(send&&ta)send.disabled=!ta.value.trim();}}).observe(root,{childList:true,subtree:true});
